							["Part"] = part,	
							["Face"] = side,	
							["TextureType"] = "Decal"	
						}	
					}	
				}	

				_(args)	
			end	
			function AddDecal(part,asset,side)	
				local args = {	
					[1] = "SyncTexture",	
					[2] = {	
						[1] = {	
							["Part"] = part,	
							["Face"] = side,	
							["TextureType"] = "Decal",	
							["Texture"] = "rbxassetid://".. asset	
						}	
					}	
				}	
				_(args)	
			end	

			function spam()	
				for i,v in game.workspace:GetDescendants() do	
					if v:IsA("BasePart") then	
						spawn(function()	
							SetLocked(v,false)	
							SpawnDecal(v,Enum.NormalId.Front)	
							AddDecal(v,124872714710239,Enum.NormalId.Front)	

							SpawnDecal(v,Enum.NormalId.Back)	
							AddDecal(v,111616848,Enum.NormalId.Back)	

							SpawnDecal(v,Enum.NormalId.Right)	
							AddDecal(v,111616664,Enum.NormalId.Right)	

							SpawnDecal(v,Enum.NormalId.Left)	
							AddDecal(v,112188192,Enum.NormalId.Left)	

							SpawnDecal(v,Enum.NormalId.Bottom)	
							AddDecal(v,111616722,Enum.NormalId.Bottom)	

							SpawnDecal(v,Enum.NormalId.Top)	
							AddDecal(v,111616450,Enum.NormalId.Top)	
						end)	
					end	
				end 	
			end	
			spam()	
end;
